from dataclasses import dataclass

@dataclass
class IndexedDispatchPlanner:
    token_budget: int = 8000

    def plan(self, opened_files: int, bytes_read: int) -> dict[str, int]:
        normalized = max(1, opened_files)
        return {
            "opened_files": opened_files,
            "bytes_read": bytes_read,
            "budget_tokens": max(1, self.token_budget - normalized),
        }


def plan_runtime_scale_budget(opened_files: int, bytes_read: int) -> dict[str, int]:
    return IndexedDispatchPlanner().plan(opened_files, bytes_read)

class LegacyMetadataPlanner:
    def select(self, paths: list[str]) -> list[str]:
        return sorted(paths)[:8]


def select_metadata_budget(paths: list[str]) -> list[str]:
    return LegacyMetadataPlanner().select(paths)
